module top_glue (
    input  wire clk,
    input  wire rst_n,
    inout  wire sda,
    inout  wire scl,
    input  wire tb_start,
    output reg tb_done
);

localparam ADDR_BYTE = 8'hA0;
localparam DATA_BYTE = 8'h11;
localparam HALF = 4;
localparam IDLE = 0;
localparam START = 1;
localparam START_HOLD = 2;
localparam BIT_LOW = 3;
localparam BIT_HIGH = 4;
localparam ACK_LOW = 5;
localparam ACK_HIGH = 6;
localparam NEXT_BYTE = 7;
localparam STOP_LOW = 8;
localparam STOP_HIGH = 9;
localparam DONE = 10;
reg [3:0] state;
reg [2:0] bit_idx;
reg [1:0] byte_idx; // 0 = address, 1 = data
reg [7:0] cur_byte;
reg [7:0] half_cnt;

task automatic advance_half;
    begin
        if (half_cnt == 3'd3) half_cnt <= 0;
        else half_cnt <= half_cnt + 1;
    end
endtask

wire half_done = (half_cnt == 3'd3);

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state         <= IDLE;
        sda_drive_low        <= 0;
        scl_drive_low        <= 0;
        tb_done       <= 0;
        half_cnt      <= 0;
        bit_idx       <= 0;
        byte_idx      <= 0;
        cur_byte      <= 8'h00;
    end else begin
        case (state)

            IDLE: begin
                sda_drive_low  <= 0;
                scl_drive_low  <= 0;
                if (tb_start) begin
                    cur_byte <= ADDR_BYTE;
                    byte_idx <= 0;
                    state    <= START;
                    half_cnt <= 0;
                end
            end

            START: begin
                scl_drive_low <= 0;
                if (half_done) begin
                    sda_drive_low   <= 1;
                    state    <= START_HOLD;
                    half_cnt <= 0;
                end else begin
                    advance_half;
                end
            end

            START_HOLD: begin
                scl_drive_low <= 0;
                if (half_done) begin
                    half_cnt <= 0;
                    scl_drive_low   <= 1;
                    bit_idx  <= 3'd7;
                    state    <= BIT_LOW;
                end else begin
                    advance_half;
                end
            end

            BIT_LOW: begin
                scl_drive_low <= 1;
                sda_drive_low <= cur_byte[bit_idx] ? 1'b0 : 1'b1;
                if (half_done) begin
                    half_cnt <= 0;
                    scl_drive_low   <= 0;
                    state    <= BIT_HIGH;
                end else begin
                    advance_half;
                end
            end

            BIT_HIGH: begin
                scl_drive_low <= 0;
                if (half_done) begin
                    half_cnt <= 0;
                    scl_drive_low   <= 1;
                    if (bit_idx == 0) begin
                        sda_drive_low <= 0;
                        state  <= ACK_LOW;
                    end else begin
                        bit_idx <= bit_idx - 1;
                        state   <= BIT_LOW;
                    end
                end else begin
                    advance_half;
                end
            end

            ACK_LOW: begin
                scl_drive_low <= 1;
                sda_drive_low <= 0;
                if (half_done) begin
                    half_cnt <= 0;
                    scl_drive_low   <= 0;
                    state    <= ACK_HIGH;
                end else begin
                    advance_half;
                end
            end

            ACK_HIGH: begin
                scl_drive_low <= 0;
                if (half_done) begin
                    half_cnt <= 0;
                    scl_drive_low   <= 1;
                    state    <= NEXT_BYTE;
                end else begin
                    advance_half;
                end
            end

            NEXT_BYTE: begin
                if (byte_idx == 0) begin
                    cur_byte <= DATA_BYTE;
                    byte_idx <= 1;
                    bit_idx  <= 3'd7;
                    state    <= BIT_LOW;
                end else begin
                    state <= STOP_LOW;
                end
            end

            STOP_LOW: begin
                scl_drive_low <= 1;
                sda_drive_low <= 1;
                if (half_done) begin
                    half_cnt <= 0;
                    scl_drive_low   <= 0;
                    state    <= STOP_HIGH;
                end else begin
                    advance_half;
                end
            end

            STOP_HIGH: begin
                scl_drive_low <= 0;
                if (half_done) begin
                    sda_drive_low <= 0;
                    tb_done       <= 1;
                    state         <= DONE;
                end else begin
                    advance_half;
                end
            end

            DONE: tb_done <= 1;

            default: state <= IDLE;
        endcase
    end
end

